from __future__ import annotations

from unittest.mock import patch

import pytest

from app.core.config import Settings
from app.libs.identity.service import FirebaseIdentityService
from tests.libs.identity.conftest import FakeAuthModule


def _service(settings: Settings | None = None) -> FirebaseIdentityService:
    return FirebaseIdentityService(settings or Settings(firebase_auth_disabled=False))


# --- Positive --------------------------------------------------------------------


def test_create_user_returns_uid_from_faked_sdk():
    fake_auth = FakeAuthModule()
    svc = _service()
    with patch("app.libs.identity.service.auth", fake_auth), patch(
        "app.libs.identity.service._init_firebase"
    ):
        uid = svc.create_user("new@example.com")
    assert uid == "fb-uid-1"
    assert fake_auth.create_user_calls == ["new@example.com"]


def test_get_user_by_email_returns_none_for_not_found():
    fake_auth = FakeAuthModule()
    svc = _service()
    with patch("app.libs.identity.service.auth", fake_auth), patch(
        "app.libs.identity.service._init_firebase"
    ):
        result = svc.get_user_by_email("nobody@example.com")
    assert result is None


def test_get_user_by_email_returns_uid_when_present():
    fake_auth = FakeAuthModule(existing={"known@example.com": "fb-uid-known"})
    svc = _service()
    with patch("app.libs.identity.service.auth", fake_auth), patch(
        "app.libs.identity.service._init_firebase"
    ):
        result = svc.get_user_by_email("known@example.com")
    assert result == "fb-uid-known"


def test_delete_user_calls_fakes_delete():
    fake_auth = FakeAuthModule(existing={"gone@example.com": "fb-uid-1"})
