# --- Negative ----------------------------------------------------------------------


def test_create_user_propagates_sdk_exception_rather_than_swallowing():
    fake_auth = FakeAuthModule()
    fake_auth.fail_next_create(RuntimeError("EmailAlreadyExistsError"))
    svc = _service()
    with patch("app.libs.identity.service.auth", fake_auth), patch(
        "app.libs.identity.service._init_firebase"
    ):
        with pytest.raises(RuntimeError, match="EmailAlreadyExistsError"):
            svc.create_user("dup@example.com")


# --- Invariants ----------------------------------------------------------------------


@pytest.mark.parametrize("call_count", [1, 2, 5])
def test_delete_user_never_raises_for_a_not_found_uid_regardless_of_call_count(call_count):
    fake_auth = FakeAuthModule()  # empty -- uid never existed
    svc = _service()
    with patch("app.libs.identity.service.auth", fake_auth), patch(
        "app.libs.identity.service._init_firebase"
    ):
        for _ in range(call_count):
            svc.delete_user("never-existed")  # must not raise
    assert len(fake_auth.delete_user_calls) == call_count


